          <CityPicker />
          <SettingsPanel />
        </div>

        <OverlapSummary view={view} />
        <TimeGrid view={view} />
      </main>

      <Legend mode={view.mode} referenceName={view.reference?.name} />
    </div>
  );
}

import type { City } from "@/data/cities";
import { formatHour, MINUTES_PER_DAY, type TimeFormat } from "@/lib/time";

export type Mode = "meeting" | "base";

export interface AwakeWindow {
  /** Hour (0–23) the day starts. */
  wakeHour: number;
  /** Hour (0–23) the day ends; exclusive. Earlier than `wakeHour` means an overnight schedule. */
  sleepHour: number;
}

export type CellState = "sleeping" | "awake" | "overlap";

export interface HourCell {
  /** Column: hour of day in the reference city (0–23). */
  refHour: number;
  /** Local wall-clock time in this city, minutes since local midnight. */
  localMinutes: number;
  /** Calendar days relative to the reference city's day (−1, 0, +1). */
  dayOffset: number;
  /** True for the first cell of a new local day — where a date label belongs. */
  startsNewDay: boolean;
  state: CellState;
}

export interface CityRow {
  city: City;
  isReference: boolean;
  offsetMinutes: number;
  /** Offset relative to the reference city, in minutes. */
  diffMinutes: number;
  cells: HourCell[];
  /** Overlap hours (reference-city hours) that apply to this row. */
  overlapHours: number[];
}

export interface Schedule {
  rows: CityRow[];
  /** Hours (reference-city time) where every city is awake. Only meaningful in meeting mode. */
  meetingOverlap: number[];
}

export const HOURS: readonly number[] = Array.from({ length: 24 }, (_, hour) => hour);

/** Is someone with this window awake during local hour `hour`? Handles overnight windows. */
export function isAwake(hour: number, { wakeHour, sleepHour }: AwakeWindow): boolean {
  if (wakeHour === sleepHour) return true; // no sleep configured: awake around the clock
  if (wakeHour < sleepHour) return hour >= wakeHour && hour < sleepHour;
  return hour >= wakeHour || hour < sleepHour;
}

export function awakeHourCount(window: AwakeWindow): number {
  return HOURS.filter((hour) => isAwake(hour, window)).length;
}

function mod(value: number, divisor: number): number {
  return ((value % divisor) + divisor) % divisor;
}

interface LocalSlot {
  localMinutes: number;
  dayOffset: number;
  awake: boolean;
}

/** Local time in a city whose offset differs by `diffMinutes`, at `refHour` in the reference city. */
function localSlot(refHour: number, diffMinutes: number, window: AwakeWindow): LocalSlot {
  const absolute = refHour * 60 + diffMinutes;
  const localMinutes = mod(absolute, MINUTES_PER_DAY);
  return {
    localMinutes,
    dayOffset: Math.floor(absolute / MINUTES_PER_DAY),
    awake: isAwake(Math.floor(localMinutes / 60), window),
  };
}

export interface ScheduleInput {
  cities: readonly City[];
  /** UTC offset (minutes) per city id, derived from the current date. */
  offsets: ReadonlyMap<string, number>;
  window: AwakeWindow;
  mode: Mode;
}

/**
 * Builds the 24-column grid anchored on the first (reference) city.
 *
 * Meeting mode: an hour is overlap when every city is awake.
 * Base mode: each city overlaps only with the reference; the reference row
 * highlights hours shared with at least one other city.
 */
export function buildSchedule({ cities, offsets, window, mode }: ScheduleInput): Schedule {
  const [reference] = cities;
  if (!reference) return { rows: [], meetingOverlap: [] };

  const refOffset = offsets.get(reference.id) ?? 0;
  const slots = cities.map((city) => {
    const diff = (offsets.get(city.id) ?? 0) - refOffset;
    return HOURS.map((hour) => localSlot(hour, diff, window));
  });
  const awakeAt = (cityIndex: number, hour: number) => slots[cityIndex]?.[hour]?.awake ?? false;

  const comparable = cities.length >= 2;
  const meetingOverlap = comparable
    ? HOURS.filter((hour) => cities.every((_, index) => awakeAt(index, hour)))
    : [];

  const baseOverlap = cities.map((_, index) =>
    comparable && index > 0 ? HOURS.filter((hour) => awakeAt(0, hour) && awakeAt(index, hour)) : [],
  );
  const baseUnion = HOURS.filter((hour) => baseOverlap.some((hours) => hours.includes(hour)));

  const rows = cities.map((city, index): CityRow => {
    const offsetMinutes = offsets.get(city.id) ?? 0;
    const overlapHours = mode === "meeting" ? meetingOverlap : index === 0 ? baseUnion : (baseOverlap[index] ?? []);
    const overlapSet = new Set(overlapHours);
    const citySlots = slots[index] ?? [];

    const cells = citySlots.map((slot, hour): HourCell => {
      const previous = citySlots[hour - 1];
      return {
        refHour: hour,
        localMinutes: slot.localMinutes,
        dayOffset: slot.dayOffset,
        startsNewDay: previous ? previous.dayOffset !== slot.dayOffset : slot.localMinutes < 60,
        state: !slot.awake ? "sleeping" : overlapSet.has(hour) ? "overlap" : "awake",
      };
    });

    return {
      city,
      isReference: index === 0,
      offsetMinutes,
      diffMinutes: offsetMinutes - refOffset,
      cells,
      overlapHours,
    };
  });

  return { rows, meetingOverlap };
}

export interface HourRange {
  /** First hour, inclusive. */
  start: number;
  /** Hour the range ends, exclusive (wraps past midnight: 22 → 2). */
  end: number;
  length: number;
}

/**
 * Collapses a set of hours into contiguous ranges, treating the day as circular
 * so 22, 23, 0, 1 reads as a single "10pm — 2am" window.
 */
export function toRanges(hours: readonly number[]): HourRange[] {
  const set = new Set(hours.filter((hour) => hour >= 0 && hour < 24));
  if (set.size === 0) return [];
  if (set.size === 24) return [{ start: 0, end: 0, length: 24 }];

  // Start scanning right after a gap so a wrap-around run is never split.
  const firstGap = HOURS.find((hour) => !set.has(hour)) ?? 0;
  const ranges: HourRange[] = [];
  let current: HourRange | null = null;

  for (let step = 1; step <= 24; step++) {
    const hour = (firstGap + step) % 24;
    if (set.has(hour)) {
      if (current) {
        current.length += 1;
        current.end = (hour + 1) % 24;
      } else {
        current = { start: hour, end: (hour + 1) % 24, length: 1 };
      }
    } else if (current) {
      ranges.push(current);
      current = null;
    }
  }
  if (current) ranges.push(current);

  return ranges.sort((a, b) => a.start - b.start);
}

/** "9am — 12pm" (end exclusive), or "All day" for a full 24-hour window. */
export function formatHourRange(range: HourRange, format: TimeFormat): string {
  if (range.length === 24) return "All day";
  return `${formatHour(range.start, format)} — ${formatHour(range.end, format)}`;
}

import { ChevronDown, Moon, SlidersHorizontal, Sun } from "lucide-react";
import { type ReactNode, type Ref, useCallback, useEffect, useId, useRef, useState } from "react";
import { SegmentedControl } from "@/components/ui/SegmentedControl";
import { type DismissReason, useDismiss } from "@/hooks/useDismiss";
import { cn } from "@/lib/cn";
import { awakeHourCount, HOURS, isAwake } from "@/lib/schedule";
import { formatHour, type TimeFormat } from "@/lib/time";
import { DEFAULT_SETTINGS, usePlanner } from "@/state/store";

const FORMAT_OPTIONS = [
  { value: "12h", label: "12-hour" },
  { value: "24h", label: "24-hour" },
] as const;

/** Toolbar button that opens the awake-window and time-format settings. */
export function SettingsPanel() {
  const settings = usePlanner((state) => state.settings);
  const updateSettings = usePlanner((state) => state.updateSettings);
  const resetSettings = usePlanner((state) => state.resetSettings);

  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const firstFieldRef = useRef<HTMLSelectElement>(null);
  const panelId = useId();

  const close = useCallback((reason: DismissReason) => {
    setOpen(false);
    if (reason === "escape") triggerRef.current?.focus();
  }, []);
  useDismiss(rootRef, open, close);

  useEffect(() => {
    if (open) firstFieldRef.current?.focus();
  }, [open]);

  const { wakeHour, sleepHour, timeFormat } = settings;
  const awakeHours = awakeHourCount(settings);
  const overnight = wakeHour > sleepHour;
  const isDefault =
    wakeHour === DEFAULT_SETTINGS.wakeHour &&
    sleepHour === DEFAULT_SETTINGS.sleepHour &&
    timeFormat === DEFAULT_SETTINGS.timeFormat;

  return (
    <div ref={rootRef} className="relative">
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={open ? panelId : undefined}
        onClick={() => setOpen((value) => !value)}
        className={cn(
          "inline-flex h-10 items-center gap-2 rounded-full border border-line-strong bg-surface pr-3 pl-3.5 text-sm shadow-[0_1px_2px_oklch(0_0_0/0.04)] transition-colors hover:border-ink-3",
          open && "border-ink-3",
        )}
      >
        <SlidersHorizontal aria-hidden className="size-4 text-ink-2" />
        <span className="text-ink-2">Awake</span>
        <span className="font-medium text-ink tabular-nums">
          {wakeHour === sleepHour ? "all day" : `${formatHour(wakeHour, timeFormat)} – ${formatHour(sleepHour, timeFormat)}`}
        </span>
        <ChevronDown aria-hidden className={cn("size-4 text-ink-3 transition-transform", open && "rotate-180")} />
      </button>

      {open && (
        <div
          id={panelId}
          role="dialog"
          aria-label="Availability settings"
          className="absolute top-full left-0 z-40 mt-2 w-[min(22rem,calc(100vw-2rem))] sm:right-0 sm:left-auto animate-pop-in rounded-2xl border border-line bg-surface p-4 shadow-pop"
        >
          <div className="mb-3 flex items-baseline justify-between gap-3">
            <h2 className="text-sm font-semibold text-ink">Awake window</h2>
            <p className="text-xs text-ink-2">Shared by every city</p>
          </div>

          <div className="grid grid-cols-2 gap-2.5">
            <HourSelect
              ref={firstFieldRef}
              label="Wake up"
              icon={<Sun aria-hidden className="size-3.5" />}
              value={wakeHour}
              format={timeFormat}
              onChange={(hour) => updateSettings({ wakeHour: hour })}
            />
            <HourSelect
              label="Go to sleep"
              icon={<Moon aria-hidden className="size-3.5" />}
              value={sleepHour}
              format={timeFormat}
              onChange={(hour) => updateSettings({ sleepHour: hour })}
            />
          </div>

          <DayStrip wakeHour={wakeHour} sleepHour={sleepHour} format={timeFormat} />

          <p className="mt-2 text-xs text-ink-2" aria-live="polite">
            <span className="font-medium text-ink tabular-nums">{awakeHours} hours</span> awake
            {wakeHour === sleepHour
              ? " — waking and sleeping at the same hour means awake around the clock."
              : overnight
                ? " · overnight schedule, crossing midnight."
                : "."}
          </p>

          <div className="mt-4 flex items-center justify-between gap-3 border-t border-line pt-4">
            <span className="text-sm font-medium text-ink">Time format</span>
            <SegmentedControl
              label="Time format"
              size="sm"
              value={timeFormat}
              options={FORMAT_OPTIONS}
              onChange={(format: TimeFormat) => updateSettings({ timeFormat: format })}
            />
          </div>

          <div className="mt-4 flex justify-end">
            <button
              type="button"
              disabled={isDefault}
              onClick={resetSettings}
              className="rounded-md text-xs font-medium text-ink-2 underline-offset-4 hover:text-ink hover:underline disabled:pointer-events-none disabled:opacity-40"
            >
              Reset to 7am – 11pm, 12-hour
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

interface HourSelectProps {
  ref?: Ref<HTMLSelectElement>;
  label: string;
  icon: ReactNode;
  value: number;
  format: TimeFormat;
  onChange: (hour: number) => void;
}

function HourSelect({ ref, label, icon, value, format, onChange }: HourSelectProps) {
  const id = useId();
  return (
    <div>
      <label htmlFor={id} className="mb-1 flex items-center gap-1.5 text-xs font-medium text-ink-2">
        {icon}
        {label}
      </label>
      <div className="relative">
        <select
          ref={ref}
          id={id}
          value={value}
          onChange={(event) => onChange(Number(event.target.value))}
          className="h-9 w-full cursor-pointer appearance-none rounded-lg border border-line-strong bg-surface pr-8 pl-3 font-mono text-sm text-ink tabular-nums transition-colors hover:border-ink-3"
        >
          {HOURS.map((hour) => (
            <option key={hour} value={hour}>
              {formatHour(hour, format)}
            </option>
          ))}
        </select>
        <ChevronDown aria-hidden className="pointer-events-none absolute top-1/2 right-2.5 size-4 -translate-y-1/2 text-ink-3" />
      </div>
    </div>
  );
}

/** A 24-segment preview of the awake window, midnight to midnight. */
function DayStrip({ wakeHour, sleepHour, format }: { wakeHour: number; sleepHour: number; format: TimeFormat }) {
  return (
    <div className="mt-4" aria-hidden>
      <div className="flex h-6 gap-px overflow-hidden rounded-md">
        {HOURS.map((hour) => (
          <div
            key={hour}
            className={cn(
              "flex-1 transition-colors duration-200",
              isAwake(hour, { wakeHour, sleepHour }) ? "bg-overlap" : "bg-surface-2",
            )}
          />
        ))}
      </div>
      <div className="mt-1 flex justify-between font-mono text-[10px] text-ink-3">
        {[0, 6, 12, 18, 24].map((hour) => (
          <span key={hour}>{formatHour(hour % 24, format)}</span>
        ))}
      </div>
    </div>
  );
}

